out = []
for r in reqs:
    probs = []
    if r.get("shared_login"): probs.append("use your own account, not a shared login")
    if r.get("level") == "admin" and r.get("needs") != "admin": probs.append("ask for least privilege")
    if not r.get("expires"): probs.append("set an expiry or review date")
    if r.get("via") == "email": probs.append("share secrets through a password manager, not email")
    if not r.get("mfa"): probs.append("turn on multi-factor authentication")
    out.append((r["system"], probs))
return out
